global sv_printf
extern printf
; printf(i, ...) -- walks the format string: each %f/%e/%g
; conversion takes the next xmm register, every other conversion the next
; integer register; then everything is laid out by position for Windows
; (variadic doubles travel in integer registers/stack slots there).
sv_printf:
    push rbp
    mov rbp, rsp
    sub rsp, 368
    ; [rsp+0..31] shadow, [rsp+32..127] stack args, [rsp+128..255] A[16]
    ; (the Windows argument list), [rsp+256..] free integer regs, [rsp+304..] xmm0..7
    mov [rsp+128], rdi
    mov [rsp+256], rsi
    mov [rsp+264], rdx
    mov [rsp+272], rcx
    mov [rsp+280], r8
    mov [rsp+288], r9
    movsd [rsp+304], xmm0
    movsd [rsp+312], xmm1
    movsd [rsp+320], xmm2
    movsd [rsp+328], xmm3
    movsd [rsp+336], xmm4
    movsd [rsp+344], xmm5
    movsd [rsp+352], xmm6
    movsd [rsp+360], xmm7
    mov r10, rdi             ; format string
    mov r11d, 1                    ; next position in A
    xor ecx, ecx                        ; integer values used
    xor edx, edx                        ; float values used
.scan:
    movzx eax, byte [r10]
    test eax, eax
    jz .scanned
    inc r10
    cmp eax, '%'
    jne .scan
.spec:
    movzx eax, byte [r10]
    test eax, eax
    jz .scanned
    inc r10
    cmp eax, '%'
    je .scan                            ; "%%" is a literal percent sign
    ; skip flags, width, precision and length modifiers
    cmp eax, '9'
    jbe .spec
    cmp eax, 'l'
    je .spec
    cmp eax, 'h'
    je .spec
    cmp eax, 'L'
    je .spec
    cmp eax, 'z'
    je .spec
    ; a conversion character
    cmp eax, 'f'
    je .flt
    cmp eax, 'e'
    je .flt
    cmp eax, 'g'
    je .flt
    cmp eax, 'F'
    je .flt
    cmp eax, 'E'
    je .flt
    cmp eax, 'G'
    je .flt
    mov rax, [rsp+256+rcx*8]
    inc ecx
    jmp .store
.flt:
    mov rax, [rsp+304+rdx*8]
    inc edx
.store:
    cmp r11d, 16
    jge .scan
    mov [rsp+128+r11*8], rax
    inc r11d
    jmp .scan
.scanned:
    ; positions 4.. go on the stack above the shadow space
    mov ecx, 4
.stk:
    cmp ecx, r11d
    jge .regs
    mov rax, [rsp+128+rcx*8]
    mov [rsp+32+rcx*8-32], rax
    inc ecx
    jmp .stk
.regs:
    mov rcx, [rsp+128]
    mov rdx, [rsp+136]
    mov r8, [rsp+144]
    mov r9, [rsp+152]
    movq xmm0, rcx
    movq xmm1, rdx
    movq xmm2, r8
    movq xmm3, r9
    call printf
    leave
    ret

