; ---- Windows -> System V entry points -------------------------------------------
; Windows expects rdi, rsi and xmm6-xmm15 to survive a call; System V code
; treats them as scratch, so these wrappers save and restore them.
%macro SAVE_WIN_REGS 0
    push rbp
    mov rbp, rsp
    push rdi
    push rsi
    sub rsp, 160
    movdqu [rsp+0], xmm6
    movdqu [rsp+16], xmm7
    movdqu [rsp+32], xmm8
    movdqu [rsp+48], xmm9
    movdqu [rsp+64], xmm10
    movdqu [rsp+80], xmm11
    movdqu [rsp+96], xmm12
    movdqu [rsp+112], xmm13
    movdqu [rsp+128], xmm14
    movdqu [rsp+144], xmm15
%endmacro
%macro RESTORE_WIN_REGS 0
    movdqu xmm6, [rsp+0]
    movdqu xmm7, [rsp+16]
    movdqu xmm8, [rsp+32]
    movdqu xmm9, [rsp+48]
    movdqu xmm10, [rsp+64]
    movdqu xmm11, [rsp+80]
    movdqu xmm12, [rsp+96]
    movdqu xmm13, [rsp+112]
    movdqu xmm14, [rsp+128]
    movdqu xmm15, [rsp+144]
    add rsp, 160
    pop rsi
    pop rdi
    pop rbp
%endmacro

; int SDL_main(int argc, char **argv) -- called by SDL2main's real main()
global SDL_main
extern beacom_main
SDL_main:
    SAVE_WIN_REGS
    mov edi, ecx
    mov rsi, rdx
    call beacom_main
    RESTORE_WIN_REGS
    ret

; void audio_cb_win64(void *userdata, Uint8 *stream, int len) -- SDL audio thread
global audio_cb_win64
extern audio_cb
audio_cb_win64:
    SAVE_WIN_REGS
    mov rdi, rcx
    mov rsi, rdx
    mov edx, r8d
    call audio_cb
    RESTORE_WIN_REGS
    ret
